import React from 'react'
import { Box, Container, List, ListItem, ListSubheader } from '@mui/material'
import { infoConstant, rulesConstant, rulesFooter, rulesHeader } from '../../constants/infoWithRules'

const containerStyles = { p: 2, borderRadius: '5px', marginBottom: '8px' }
export default function RulesContainer() {

    return (
        <Container>
            {
                infoConstant.map(infoItem => (
                    <Box key={infoItem.id} sx={containerStyles}><div dangerouslySetInnerHTML={{ __html: `<${infoItem.component}>${infoItem.content}</${infoItem.component}>` }} /></Box>
                ))
            }
            <Box sx={{ ...containerStyles, p: 0, paddingY: 2 }}>
                <List
                    sx={{
                        width: '100%',
                        padding: '0'
                    }}
                    component="ol"
                    aria-labelledby="nested-list-subheader"
                    subheader={
                        <ListSubheader
                            sx={{ fontSize: 18, fontWeight: 700, lineHeight: '20px', color: 'initial' }}
                            component="h3"
                            id="nested-list-subheader"
                            dangerouslySetInnerHTML={{ __html: rulesHeader }} />
                    }
                >
                    {
                        rulesConstant.map((rule, index) => (
                            <ListItem><div dangerouslySetInnerHTML={{ __html: `${index + 1}. ${rule}` }} /></ListItem>
                        ))
                    }
                    {
                        <ListItem><div dangerouslySetInnerHTML={{ __html: rulesFooter }} /></ListItem>
                    }
                </List>
                <Box></Box>
            </Box>
        </Container>
    )
}